From 198323b480484094a27f9f36b180e82017e8ced9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:57:32 +0100
Subject: [PATCH] calendar: let days of other months open their month

Days of the previous and next month were disabled, so clicking them or
reaching them with the arrow keys did nothing. Now they go to their
month and select or focus that day, drawn with enough contrast for AA.

BUG: 528382
---
 components/calendar/qml/DayDelegate.qml  |  6 ++--
 components/calendar/qml/DaysCalendar.qml | 11 ++++--
 components/calendar/qml/MonthView.qml    | 46 ++++++++++++++++++++++++
 3 files changed, 58 insertions(+), 5 deletions(-)

diff --git a/components/calendar/qml/DayDelegate.qml b/components/calendar/qml/DayDelegate.qml
index 2070c055ed..e1b840b9c0 100644
--- a/components/calendar/qml/DayDelegate.qml
+++ b/components/calendar/qml/DayDelegate.qml
@@ -79,8 +79,7 @@ PlasmaComponents.AbstractButton {
             return "calendarCell-" + yearNumber + "-" + model.monthNumber + "-" + model.dayNumber;
         }
     }
-    hoverEnabled: isCurrent
-    enabled: isCurrent
+    hoverEnabled: true

     // type: either PlasmaCalendar.DaysModel or an equivalent ListModel
     required property QtObject dayModel
@@ -178,6 +177,7 @@ PlasmaComponents.AbstractButton {
         // Basically, only active when dayStyle.dayModel is PlasmaCalendar.DaysModel
         // and thus dateMatchingPrecision is PlasmaCalendar.Calendar.MatchYearMonthAndDay
         active: dayStyle.model.eventCount !== undefined && dayStyle.model.eventCount > 0
+        opacity: label.opacity
         anchors.top: parent.top
         anchors.topMargin: Kirigami.Units.largeSpacing
         anchors.horizontalCenter: parent.horizontalCenter
@@ -240,7 +240,7 @@ PlasmaComponents.AbstractButton {
             verticalAlignment: Text.AlignVCenter
             text: dayStyle.model.label || dayStyle.model.dayLabel
             textFormat: Text.PlainText
-            opacity: dayStyle.isCurrent ? 1.0 : 0.5
+            opacity: dayStyle.isCurrent ? 1.0 : 0.7
             wrapMode: Text.NoWrap
             elide: Text.ElideRight
         }
diff --git a/components/calendar/qml/DaysCalendar.qml b/components/calendar/qml/DaysCalendar.qml
index 79be5996c2..fcac00f04c 100644
--- a/components/calendar/qml/DaysCalendar.qml
+++ b/components/calendar/qml/DaysCalendar.qml
@@ -19,6 +19,7 @@ Item {
     id: daysCalendar

     signal activated(int index, var date, var item)
+    signal outsideEntryFocused(var date)

     property int rows
     property int columns
@@ -180,18 +181,24 @@ Item {
                 KeyNavigation.tab: daysCalendar.KeyNavigation.tab

                 Keys.onUpPressed: event => {
-                    if (index >= daysCalendar.columns && (gridRepeater.itemAt(index - daysCalendar.columns) as DayDelegate).isCurrent) {
+                    if (index >= daysCalendar.columns) {
                         gridRepeater.itemAt(index - daysCalendar.columns).forceActiveFocus(Qt.TabFocusReason);
                     } else {
                         event.accepted = false;
                     }
                 }
                 Keys.onDownPressed: event => {
-                    if (index < (daysCalendar.rows - 1) * daysCalendar.columns && (gridRepeater.itemAt(index + daysCalendar.columns) as DayDelegate).isCurrent) {
+                    if (index < (daysCalendar.rows - 1) * daysCalendar.columns) {
                         gridRepeater.itemAt(index + daysCalendar.columns).forceActiveFocus(Qt.TabFocusReason);
                     }
                 }

+                onActiveFocusChanged: {
+                    if (activeFocus && !isCurrent && (focusReason === Qt.TabFocusReason || focusReason === Qt.BacktabFocusReason)) {
+                        daysCalendar.outsideEntryFocused(thisDate);
+                    }
+                }
+
                 onClicked: {
                     daysCalendar.activated(index, model, this)
                 }
diff --git a/components/calendar/qml/MonthView.qml b/components/calendar/qml/MonthView.qml
index 619852a770..3d798485ae 100644
--- a/components/calendar/qml/MonthView.qml
+++ b/components/calendar/qml/MonthView.qml
@@ -45,6 +45,9 @@ Item {

     property date showDate: new Date()

+    // Day to give keyboard focus to once showMonthOf() has changed the month
+    property var dayToFocus: null
+
     property int borderWidth: 1
     property real borderOpacity: 0.4

@@ -161,6 +164,41 @@ Item {
         currentView.decrementCurrentIndex();
     }

+    /**
+     * Go to the month containing the given date and focus its cell.
+     */
+    function showMonthOf(date: date) {
+        const offset = (date.getFullYear() - calendarBackend.year) * 12 + date.getMonth() + 1 - calendarBackend.month;
+        if (offset === 0) {
+            return;
+        }
+        dayToFocus = date;
+        if (offset > 0) {
+            nextView();
+        } else {
+            previousView();
+        }
+    }
+
+    Connections {
+        target: calendarBackend
+        enabled: root.dayToFocus !== null
+        function onDisplayedDateChanged() {
+            Qt.callLater(() => {
+                const date = root.dayToFocus;
+                root.dayToFocus = null;
+                const daysCalendar = mainDaysCalendar.itemAtIndex(1) as DaysCalendar;
+                for (let i = 0; date && daysCalendar && i < daysCalendar.repeater.count; i++) {
+                    const day = daysCalendar.repeater.itemAt(i) as DayDelegate;
+                    if (day.isCurrent && day.thisDate.toDateString() === date.toDateString()) {
+                        day.forceActiveFocus(Qt.TabFocusReason);
+                        break;
+                    }
+                }
+            });
+        }
+    }
+
     /**
      * \return CalendarView
      */
@@ -397,6 +435,14 @@ Item {
                     if (date.subLabel) {
                         root.currentDateAuxilliaryText = date.subLabel;
                     }
+
+                    if (!item.isCurrent) {
+                        root.showMonthOf(selectedDate);
+                    }
+                }
+
+                onOutsideEntryFocused: date => {
+                    root.showMonthOf(date);
                 }
             }
         }
-- 
2.53.0
